 internal static class FlowKotlin {
  internal static string TemplateNumber(double value){return Number(value);}
  internal static FlowSourceText Generate(FlowSource.Program program){using(var stream=typeof(FlowKotlin).Assembly.GetManifestResourceStream("Frociart.Source.KotlinRuntime.kt")){if(stream==null)throw new InvalidOperationException("Il supporto Kotlin non è disponibile.");using(var reader=new StreamReader(stream,Encoding.UTF8))return Generate(program,reader.ReadToEnd());}}
  internal static FlowSourceText Generate(FlowSource.Program program,string runtime,string objectName="Programma"){if(String.IsNullOrWhiteSpace(runtime))throw new ArgumentException("Il supporto Kotlin è vuoto.");if(objectName==null||!Regex.IsMatch(objectName,@"\A[A-Za-z_][A-Za-z_0-9]*\z")||Keywords.Contains(objectName)||objectName.All(c=>c=='_')||new[]{"Value","Vector","Variables","TypeSpec","ArrayCell","ArrayArgument","TextFiles","Turtle","Problem","Intrinsics","FcRuntime"}.Contains(objectName)||objectName.StartsWith("FcScope",StringComparison.Ordinal))throw new ArgumentException("Nome Kotlin non valido.");return new Writer(program).Generate(runtime,objectName);}
  internal static string Literal(string text){if(text==null)return "null";var b=new StringBuilder("\"");foreach(char c in text){if(c=='"')b.Append("\\\"");else if(c=='\\')b.Append("\\\\");else if(c=='$')b.Append("\\$");else if(c=='\n')b.Append("\\n");else if(c=='\r')b.Append("\\r");else if(c=='\t')b.Append("\\t");else if(c<32||c>126)b.Append("\\u").Append(((int)c).ToString("x4"));else b.Append(c);}return b.Append('"').ToString();}
  static readonly HashSet<string> Keywords=new HashSet<string>(("as break class continue do else false for fun if in interface is null object package return super this throw true try typealias typeof val var when while by catch constructor delegate dynamic field file finally get import init param property receiver set setparam where actual abstract annotation companion const crossinline data enum expect external final infix inline inner internal lateinit noinline open operator out override private protected public reified sealed suspend tailrec vararg value field it args").Split(' '),StringComparer.Ordinal);
  static string Identifier(string name){var b=new StringBuilder();foreach(char c in name)if(c>='a'&&c<='z'||c>='A'&&c<='Z'||c>='0'&&c<='9'||c=='_')b.Append(c);else b.Append("_u").Append(((int)c).ToString("x4"));string value=b.ToString();if(value.Length==0||Char.IsDigit(value[0])||value.StartsWith("fc",StringComparison.Ordinal)||Keywords.Contains(value)||value.All(c=>c=='_'))value="flowValue_"+value;return value;}
  static string Unique(string seed,HashSet<string> names){string value=seed;int n=2;while(!names.Add(value))value=seed+"_"+(n++).ToString(CultureInfo.InvariantCulture);return value;}
  static string Bool(bool value){return value?"true":"false";}
  static string Number(double value){if(value==0)return "Value.number(0.0)";if(Math.Abs(value)<=9000000000d){long power=1;for(int digits=0;digits<=6;digits++,power*=10){double scaled=value*power;if(scaled!=Math.Floor(scaled))continue;string text=((long)Math.Abs(scaled)).ToString(CultureInfo.InvariantCulture).PadLeft(digits+1,'0');if(digits>0)text=text.Insert(text.Length-digits,".");if(value<0)text="-"+text;if(Double.Parse(text,CultureInfo.InvariantCulture)==value)return "Value.number("+text+(digits==0?".0":"")+")";}}return "Value.number(java.lang.Double.longBitsToDouble(java.lang.Long.parseUnsignedLong(\""+BitConverter.DoubleToInt64Bits(value).ToString("x16")+"\", 16)))";}
  sealed class Symbol {internal string Name,Original;}
  sealed class Helper {internal string Name;internal FlowSource.Expression Expression;internal FlowSource.Block Block;internal HashSet<string> Staged;internal bool Track;}
  sealed class Writer {
   readonly FlowSource.Program program;readonly FlowSourceText.Builder output;readonly bool references;readonly Dictionary<string,string> functions=new Dictionary<string,string>(),classes=new Dictionary<string,string>();
   readonly HashSet<string> globals=new HashSet<string>(("Value Vector Variables Intrinsics TypeSpec ArrayCell ArrayArgument FcRuntime TextFiles Turtle Problem java kotlin listOf arrayOf String Double Int Long Boolean Array List HashMap ArrayList Runtime System Math Programma fc problem finite lower shortText roundAway parseInput run").Split(' '),StringComparer.Ordinal);
   FlowSource.Scope scope;Dictionary<string,Symbol> names;List<Symbol> symbols;Dictionary<string,string> methods;List<Helper> helpers;int temporary;bool inline;
   internal Writer(FlowSource.Program p){program=p;output=new FlowSourceText.Builder(p,"kotlin");references=p.Scopes.SelectMany(s=>s.Parameters).Any(x=>x.ByReference);int index=0;var used=globals;foreach(var s in p.Scopes){classes[s.Id??""]="FcScope"+(index++);if(s.Id!=null)functions[s.Id]=Unique("flow_"+Identifier(s.Name),used);}}
   void Line(string text,int indent,FlowSource.Block block=null){output.AddLine(text,indent,block==null?new FlowSourceText.Origin[0]:new[]{new FlowSourceText.Origin(scope.Id,block.Id)});}
   internal FlowSourceText Generate(string runtime,string objectName){Line("// Generato con Frociart — autore del software: mamt104",0);Line("// Progetto: "+Literal(program.Title),0);Line("// Kotlin/JVM 1.9+. kotlinc Programma.kt -include-runtime -d Programma.jar; java -jar Programma.jar",0);Line("object "+objectName+" {",0);Line("private var fc = FcRuntime()",1);Line("@JvmStatic fun main(args: Array<String>) {",1);Line("if (!fc.run({ FcScope0().run() }, true)) kotlin.system.exitProcess(1)",2);Line("}",1);
    foreach(var s in program.Scopes){if(s.Id!=null){var used=new HashSet<string>(globals,StringComparer.Ordinal);var args=new List<string>();foreach(var p in s.Parameters)args.Add(Unique(Identifier(p.Name),used));bool value=s.ReturnType!=FlowDataType.Void;Line("private fun "+functions[s.Id]+"("+String.Join(", ",args.Select(a=>a+": Value"))+"): "+(value?"Value":"Value?")+" {",1);Line("return "+(value?"fc.requireValue(":"")+classes[s.Id]+"().run("+String.Join(", ",args)+")"+(value?")":""),2);Line("}",1);}Scope(s);}
    Line("",1);Line("// --- Supporto dei tipi, dei limiti e delle operazioni di Frociart ---",1);foreach(string text in runtime.Replace("\r\n","\n").Replace('\r','\n').Split('\n'))Line(text,1);Line("}",0);return output.Build();
   }
   void Collect(FlowSource.Expression expression,Action<string> add){if(expression==null)return;if(expression.Kind==FlowSource.ExpressionKind.Variable)add(expression.Text);foreach(var child in expression.Children)Collect(child,add);}
   bool Inline(FlowSource.Scope current){int cost=0;var pending=new Stack<FlowSource.Expression>();Action<FlowSource.Expression> add=e=>{if(e!=null)pending.Push(e);};foreach(var b in current.Blocks){var o=b.Operation;cost+=64+o.Writes.Count*48;add(o.Value);if(o.Input!=null)add(o.Input.Index);if(o.Declaration!=null){cost+=o.Declaration.Names.Count*32;add(o.Declaration.Size);}foreach(var w in o.Writes){add(w.Value);add(w.Target.Index);}while(pending.Count>0){var e=pending.Pop();cost+=32;if(cost>12000)return false;foreach(var child in e.Children)add(child);}if(cost>12000)return false;}return true;}
   void Scope(FlowSource.Scope current){scope=current;temporary=0;inline=Inline(current);names=new Dictionary<string,Symbol>(StringComparer.OrdinalIgnoreCase);symbols=new List<Symbol>();helpers=new List<Helper>();methods=new Dictionary<string,string>();var used=new HashSet<string>(globals,StringComparer.Ordinal);Action<string> add=name=>{if(name!=null&&!names.ContainsKey(name)){var symbol=new Symbol{Name=Unique(Identifier(name),used),Original=name};names.Add(name,symbol);symbols.Add(symbol);}};foreach(var p in scope.Parameters)add(p.Name);int index=0;foreach(var b in scope.Blocks){methods[b.Id]="fc_block"+(index++);var o=b.Operation;if(o.Input!=null){add(o.Input.Name);Collect(o.Input.Index,add);}if(o.Declaration!=null){foreach(string name in o.Declaration.Names)add(name);Collect(o.Declaration.Size,add);}foreach(var w in o.Writes){add(w.Target.Name);Collect(w.Value,add);Collect(w.Target.Index,add);}Collect(o.Value,add);}
    Line("",1);foreach(var n in scope.Notes)Line("// Annotazione: "+Literal(n.Text),1,n);foreach(var b in scope.Blocks.Where(b=>!String.IsNullOrEmpty(b.Comment)))Line("// Nota: "+Literal(b.Comment),1,b);
    Line("private class "+classes[scope.Id??""]+" {",1);foreach(var symbol in symbols){Line("private var "+symbol.Name+": Value? = null",2);Line("private var fc_type_"+symbol.Name+": TypeSpec? = null",2);}Line("fun run("+String.Join(", ",scope.Parameters.Select((p,i)=>"fc_arg"+i+": Value"))+"): Value? {",2);Line("fc.guardCall()",3);index=0;foreach(var p in scope.Parameters)Line(names[p.Name].Name+" = fc."+(p.ByReference?"checkReference":"checkType")+"(fc_arg"+(index++)+", "+(int)p.Type+(p.ByReference?"":", "+Bool(p.IsArray))+")",3);
    Line("fc.enter("+Literal(scope.Id==null?null:scope.Name)+", arrayOf("+String.Join(", ",scope.Parameters.Select(p=>Literal(names[p.Name].Original)))+"), arrayOf("+String.Join(", ",scope.Parameters.Select((p,i)=>"fc_arg"+i))+"), "+Bool(references)+")",3);Line("try {",3);Line("fc.checkMemory()",4);var plan=FlowSourcePlan.Create(scope);if(plan.Structured)Statements(plan.Statements,4);else Explicit(4);Line("} catch (failure: Throwable) {",3);Line("fc.captureError(); throw failure",4);Line("} finally { fc.leave() }",3);Line("}",2);
    if(!inline)foreach(var b in scope.Blocks)Instruction(b,2,false);else foreach(var b in scope.Blocks.Where(b=>!b.Reachable))Line("// Blocco non raggiungibile, escluso dall’esecuzione: "+Literal(b.Text),2,b);for(int i=0;i<helpers.Count;i++){var h=helpers[i];Line("private fun "+h.Name+"(): Value {",2,h.Block);Line("return "+Expression(h.Expression,h.Block,h.Staged,0,h.Track),3,h.Block);Line("}",2,h.Block);}Line("}",1);
   }
   string Declaration(string name){return "fc_type_"+names[name].Name;}
   string Parameter(string name){var p=scope.Parameters.FirstOrDefault(x=>x.Name.Equals(name,StringComparison.OrdinalIgnoreCase));return p==null?"null":"TypeSpec("+(int)p.Type+", "+Bool(p.IsArray)+", 0)";}
   string Name(string name,HashSet<string> staged){var symbol=names[name];return references?"fc.lookup("+Literal(symbol.Original)+")":"fc.value("+(staged.Contains(name.ToLowerInvariant())?"fc.staged("+Literal(symbol.Original)+")":symbol.Name)+", "+Literal(symbol.Original)+")";}
   bool Calls(FlowSource.Expression e){return e!=null&&(e.FunctionId!=null||e.Children.Any(Calls));}
   string Expression(FlowSource.Expression e,FlowSource.Block b){return Expression(e,b,new HashSet<string>(),0,false);}
   string Expression(FlowSource.Expression e,FlowSource.Block b,HashSet<string> staged,int depth,bool track){if(e==null)return "null";if(depth==0)track|=Calls(e);if(depth>=24){string helper="fc_expr"+(++temporary);helpers.Add(new Helper{Name=helper,Expression=e,Block=b,Staged=new HashSet<string>(staged),Track=track});return helper+"()";}int key=track?++temporary:0;Func<FlowSource.Expression,string> child=c=>{string value=Expression(c,b,staged,depth+1,track);return track?"fc.hold("+key+", "+value+")":value;};Func<string,string> finish=value=>track&&e.Children.Count>0?"fc.release("+key+", "+value+")":value;
    switch(e.Kind){case FlowSource.ExpressionKind.Number:return Number(e.Number);case FlowSource.ExpressionKind.Text:return "Value.text("+Literal(e.Text)+")";case FlowSource.ExpressionKind.Boolean:return "Value.bool("+Bool(e.Boolean)+")";case FlowSource.ExpressionKind.Variable:return Name(e.Text,staged);case FlowSource.ExpressionKind.Vector:return finish("Value.vector(listOf("+String.Join(", ",e.Children.Select(child))+"))");case FlowSource.ExpressionKind.Unary:return finish("fc.unary("+Literal(e.Text)+", "+child(e.Children[0])+")");
     case FlowSource.ExpressionKind.Index:{string target=child(e.Children[0]);return finish(references&&e.Children[0].Kind==FlowSource.ExpressionKind.Variable?"fc.atName("+Literal(names[e.Children[0].Text].Original)+", { "+child(e.Children[1])+" })":"fc.at("+target+", { "+child(e.Children[1])+" })");}
