     case FlowSource.ExpressionKind.Binary:{string a=child(e.Children[0]),right=child(e.Children[1]);return e.Text=="and"||e.Text=="or"?finish("Value.bool("+a+".asBoolean() "+(e.Text=="and"?"&&":"||")+" "+right+".asBoolean())"):finish("fc.binary("+Literal(e.Text)+", "+a+", "+right+")");}default:throw new ArgumentException("Espressione Kotlin non supportata.");}
   }
   string Condition(FlowSource.Block b){return inline?"fc.test { "+Expression(b.Operation.Value,b)+" }":methods[b.Id]+"()!!.asBoolean()";}
   void Statements(IEnumerable<FlowSourcePlan.Statement> list,int indent){foreach(var s in list){if(s.Kind==FlowSourcePlan.Kind.Instruction){if(inline)Instruction(s.Block,indent,true);else Line((s.Block.Kind==NodeKind.End?"return ":"")+methods[s.Block.Id]+"()",indent,s.Block);}else if(s.Kind==FlowSourcePlan.Kind.Repeat){Line("do {",indent,s.EntryBlock);Statements(s.Body,indent+1);Line("} while ("+(s.LoopOnTrue?"":"!")+"("+Condition(s.Block)+"))",indent,s.Block);}else if(s.Kind==FlowSourcePlan.Kind.While){Line("while ("+(s.LoopOnTrue?"":"!")+"("+Condition(s.Block)+")) {",indent,s.Block);Statements(s.Body,indent+1);Line("}",indent,s.Block);}else{Line("if ("+Condition(s.Block)+") {",indent,s.Block);Statements(s.Body,indent+1);Line("} else {",indent,s.Block);Statements(s.Otherwise,indent+1);Line("}",indent,s.Block);}}}
   void Explicit(int indent){Line("// Collegamenti espliciti per conservare questo grafo.",indent);Line("var fc_next = "+Literal(scope.StartId),indent);Line("while (true) {",indent);Line("when (fc_next) {",indent+1);foreach(var b in scope.Blocks){Line(Literal(b.Id)+" -> {",indent+2,b);if(b.Kind==NodeKind.Decision)Line("fc_next = if ("+Condition(b)+") "+Literal(b.Next("true"))+" else "+Literal(b.Next("false")),indent+3,b);else if(b.Kind==NodeKind.End){if(inline)Instruction(b,indent+3,true);else Line("return "+methods[b.Id]+"()",indent+3,b);}else{if(inline)Instruction(b,indent+3,true);else Line(methods[b.Id]+"()",indent+3,b);Line("fc_next = "+Literal(b.Next("next")),indent+3,b);}Line("}",indent+2,b);}Line("else -> problem(\"Collegamento non valido nel sorgente modificato.\")",indent+2);Line("}",indent+1);Line("}",indent);}
   string ConvertValue(string value,string name){return "fc.convert("+value+", "+Declaration(name)+", "+Parameter(name)+")";}
   void Instruction(FlowSource.Block b,int indent,bool inPlace){var o=b.Operation;if(!inPlace)Line("private fun "+methods[b.Id]+"(): Value? {",indent,b);else if(b.Kind==NodeKind.Declare)Line("run {",indent,b);int body=indent+(!inPlace||b.Kind==NodeKind.Declare?1:0);Action<string> emit=text=>Line(text,body,b);
    if(b.Kind==NodeKind.Decision){emit("return Value.bool(fc.test { "+Expression(o.Value,b)+" })");Line("}",indent,b);return;}emit(b.Kind==NodeKind.Input?"fc.guard()":"fc.step()");
    if(b.Kind==NodeKind.End){if(scope.Id==null)emit("fc.finishFiles()");emit(scope.Id==null||scope.ReturnType==FlowDataType.Void?"return null":"return fc.checkType("+Expression(o.Value,b)+", "+(int)scope.ReturnType+", "+Bool(scope.ReturnIsArray)+")");if(!inPlace)Line("}",indent,b);return;}
    if(b.Kind==NodeKind.Process){emit("fc.begin()");var staged=new HashSet<string>();var parts=new List<string>();foreach(var w in o.Writes){if(!inPlace){string part="fc_assign"+(++temporary);parts.Add(part);emit(part+"()");continue;}string value=Expression(w.Value,b,staged,0,false);if(w.Target.Index!=null)value=(references?"fc.setAfterName("+value+", "+Literal(names[w.Target.Name].Original):"fc.setAfter("+value+", "+Name(w.Target.Name,staged))+", { "+Expression(w.Target.Index,b,staged,0,false)+" })";emit("fc.stage("+Literal(names[w.Target.Name].Original)+", "+ConvertValue(value,w.Target.Name)+(references&&w.Target.Index!=null?", true, true":"")+")");staged.Add(w.Target.Name.ToLowerInvariant());}emit("fc.commit()");foreach(string name in o.Writes.Select(w=>w.Target.Name).Distinct(StringComparer.OrdinalIgnoreCase))emit(names[name].Name+" = fc.variable("+Literal(names[name].Original)+")");if(inPlace)return;emit("return null");Line("}",indent,b);staged.Clear();for(int i=0;i<o.Writes.Count;i++){var w=o.Writes[i];Line("private fun "+parts[i]+"() {",indent,b);string value=Expression(w.Value,b,staged,0,false);if(w.Target.Index!=null)value=(references?"fc.setAfterName("+value+", "+Literal(names[w.Target.Name].Original):"fc.setAfter("+value+", "+Name(w.Target.Name,staged))+", { "+Expression(w.Target.Index,b,staged,0,false)+" })";Line("fc.stage("+Literal(names[w.Target.Name].Original)+", "+ConvertValue(value,w.Target.Name)+(references&&w.Target.Index!=null?", true, true":"")+")",indent+1,b);Line("}",indent,b);staged.Add(w.Target.Name.ToLowerInvariant());}return;}
    if(b.Kind==NodeKind.Declare){var d=o.Declaration;emit("val fc_size = Intrinsics.integer("+(d.IsArray?Expression(d.Size,b):"Value.number(0.0)")+", 0, 1024, \"La dimensione\")");emit("fc.begin()");foreach(string name in d.Names)emit("fc.stage("+Literal(names[name].Original)+", fc.initial("+(int)d.Type+", "+Bool(d.IsArray)+", fc_size), false)");emit("fc.commit(true)");foreach(string name in d.Names){emit(names[name].Name+" = fc.variable("+Literal(names[name].Original)+")");emit(Declaration(name)+" = TypeSpec("+(int)d.Type+", "+Bool(d.IsArray)+", fc_size)");}}
    else if(b.Kind==NodeKind.Input||b.Kind==NodeKind.ReadFile){var t=o.Input;emit(names[t.Name].Name+" = fc."+(b.Kind==NodeKind.Input?"read(":"readFile(")+Literal(names[t.Name].Original)+", "+(b.Kind==NodeKind.Input?Literal(b.Prompt??"")+", ":"")+Declaration(t.Name)+", "+Parameter(t.Name)+", "+(t.Index==null?"null, null":Name(t.Name,new HashSet<string>())+", { "+Expression(t.Index,b)+" }")+")");if(b.Kind==NodeKind.Input)emit("fc.step()");}
    else if(b.Kind!=NodeKind.Start&&b.Kind!=NodeKind.Pause){if(b.Kind==NodeKind.OpenFile)emit("fc.requireClosed("+Bool(o.FileReading)+")");if(b.Kind==NodeKind.WriteFile)emit("fc.requireWrite()");string value=Expression(o.Value,b);switch(b.Kind){case NodeKind.Output:emit("fc.emit("+value+", "+Bool(o.OutputNewline)+")");break;case NodeKind.Call:emit(value);break;case NodeKind.OpenFile:emit("fc.openFile("+Bool(o.FileReading)+", "+value+")");break;case NodeKind.WriteFile:emit("fc.writeFile("+value+", "+Bool(o.FileNewline)+")");break;case NodeKind.CloseFile:emit("fc.closeFile("+Bool(o.FileReading)+")");break;case NodeKind.TurtleForward:case NodeKind.TurtleTurn:case NodeKind.TurtleHome:case NodeKind.TurtleClear:case NodeKind.TurtlePen:emit("fc.turtle("+(int)b.Kind+", "+value+", "+Bool(b.Kind==NodeKind.TurtleForward?o.TurtleDraw:o.TurtleLeft)+")");break;default:throw new ArgumentException("Blocco Kotlin non supportato.");}}
    if(!inPlace){emit("return null");Line("}",indent,b);}else if(b.Kind==NodeKind.Declare)Line("}",indent,b);
   }
  }
